import sys
import subprocess
import os

def get_user_info(username):
    try:
        # Exécuter la commande cat /etc/passwd | grep username
        result = subprocess.run(
            ['cat', '/etc/passwd', '|', 'grep', username],
            shell=True,
            capture_output=True,
            text=True,
            check=False
        )

        # Vérifier si la commande a échoué
        if result.returncode != 0:
            if result.stderr:
                print(f"Erreur : {result.stderr.strip()}", file=sys.stderr)
            else:
                print(f"Utilisateur '{username}' introuvable dans /etc/passwd.", file=sys.stderr)
            return

        # Vérifier si la sortie est vide
        if not result.stdout.strip():
            print(f"Utilisateur '{username}' introuvable dans /etc/passwd.", file=sys.stderr)
            return

        # Afficher les informations utilisateur
        print(result.stdout.strip())

    except PermissionError:
        print("Erreur : Permission refusée pour accéder à /etc/passwd.", file=sys.stderr)
    except Exception as e:
        print(f"Erreur inattendue : {e}", file=sys.stderr)

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <nom_utilisateur>", file=sys.stderr)
        sys.exit(1)

    username = sys.argv[1]
    get_user_info(username)

if __name__ == "__main__":
    main()

